// ====== غيّر أرقامك هنا ======
const fabrics = {
  cotton:         { name_ar: "قطن",          name_en: "Cotton",         raw_material_price: 110, unit_price: 70 },
  twill:          { name_ar: "توين",          name_en: "Twill",          raw_material_price: 140, unit_price: 80 },
  gabardine:      { name_ar: "جبردين",        name_en: "Gabardine",      raw_material_price: 130, unit_price: 80 },
  polyester_mix:  { name_ar: "قطن مخلوط",     name_en: "Poly-cotton mix", raw_material_price: 95,  unit_price: 65 }
};

// كل موديل (قسم) بسعره الخاص - اكتب سعر كل موديل عندك هنا
const models = {
  security: { name_ar: "يونيفورم الأمن", price: 0 },
  medical: { name_ar: "يونيفورم طبي", price: 0 },
  doctors: { name_ar: "يونيفورم أطباء", price: 0 },
  nursing: { name_ar: "يونيفورم تمريض", price: 0 },
  restaurant: { name_ar: "يونيفورم مطاعم", price: 0 },
  cafe: { name_ar: "يونيفورم كافيهات", price: 0 },
  hotel: { name_ar: "يونيفورم فنادق", price: 0 },
  corporate: { name_ar: "يونيفورم شركات", price: 0 },
  factory: { name_ar: "يونيفورم مصانع", price: 0 },
  construction: { name_ar: "يونيفورم مقاولات", price: 0 },
  petroleum: { name_ar: "يونيفورم بترول", price: 0 },
  cleaning: { name_ar: "يونيفورم نظافة", price: 0 },
  school: { name_ar: "يونيفورم مدارس", price: 0 },
  chef: { name_ar: "ملابس شيف", price: 0 },
  "hi-vis": { name_ar: "سترات عالية الوضوح", price: 0 },
  safety: { name_ar: "ملابس السلامة", price: 0 },
  coveralls: { name_ar: "أفرول", price: 0 },
  polo: { name_ar: "بولو شيرت", price: 0 },
  tshirts: { name_ar: "تي شيرت", price: 0 },
  jackets: { name_ar: "جاكيتات", price: 0 },
  custom: { name_ar: "يونيفورم حسب الطلب", price: 0 },
  accessories: { name_ar: "إكسسوارات", price: 0 }
};

// كل شكل/قصة بسعره الخاص - غيّر الأسماء والأسعار براحتك
const shapes = {
  classic: { name_ar: "قصة كلاسيك", price: 0 },
  sport: { name_ar: "قصة سبور", price: 0 },
  slim: { name_ar: "قصة ضيقة", price: 0 },
  custom_shape: { name_ar: "شكل حسب الطلب", price: 0 }
};

const embroideryPrice = 25;

// كل صف هنا: أقل عدد قطع تبدأ منه الخصم، ونسبة الخصم
const quantityTiers = [
  { min_qty: 1,    discount_percent: 0 },
  { min_qty: 50,   discount_percent: 5 },
  { min_qty: 100,  discount_percent: 10 },
  { min_qty: 300,  discount_percent: 15 },
  { min_qty: 1000, discount_percent: 20 }
];
// ====== لغاية هنا بس اللي تغيره عادة ======

const body = $input.first().json.body || $input.first().json;
const quantity = Number(body.quantity) || 1;
const fabricId = body.fabricId || 'cotton';
const modelId = body.modelId || 'security';
const shapeId = body.shapeId || 'classic';
const embroideries = Array.isArray(body.embroideries) ? body.embroideries : [];
const totalLogos = embroideries.reduce((sum, e) => sum + (Number(e.count) || 0), 0);

const fabric = fabrics[fabricId] || fabrics.cotton;
const model = models[modelId] || Object.values(models)[0];
const shape = shapes[shapeId] || Object.values(shapes)[0];
const embroideryExtra = totalLogos * embroideryPrice;

const perPieceBeforeDiscount =
  fabric.raw_material_price + fabric.unit_price + model.price + shape.price + embroideryExtra;

const tier = quantityTiers
  .slice()
  .sort((a, b) => a.min_qty - b.min_qty)
  .filter(t => quantity >= t.min_qty)
  .pop() || quantityTiers[0];

const perPiece = Math.round(perPieceBeforeDiscount * (1 - tier.discount_percent / 100));
const total = perPiece * quantity;

// توصية بسيطة — غيّر أو زوّد الشروط زي ما يناسبك
let recommendation_ar = '';
if (quantity >= 300 && fabricId !== 'polyester_mix') {
  recommendation_ar = 'بما إن العدد كبير، خامة القطن المخلوط ممكن توفرلك في التكلفة الإجمالية من غير ما تأثر كتير على الجودة.';
} else if (fabricId === 'twill') {
  recommendation_ar = 'توين اختيار قوي ومتين، مناسب جدًا للاستخدام اليومي المكثف.';
} else if (fabricId === 'gabardine') {
  recommendation_ar = 'جبردين بيدي مظهر رسمي أنيق، مناسب لقطاعات زي الفنادق والشركات.';
} else if (fabricId === 'cotton') {
  recommendation_ar = 'القطن مريح وتنفسه عالي، اختيار موفق للأجواء الحارة والمطاعم.';
}

return [{
  json: {
    fabric_name_ar: fabric.name_ar,
    fabric_name_en: fabric.name_en,
    model_name_ar: model.name_ar,
    shape_name_ar: shape.name_ar,
    per_piece_price: perPiece,
    quantity,
    total_logos: totalLogos,
    total_price: total,
    discount_percent: tier.discount_percent,
    currency: 'EGP',
    recommendation_ar
  }
}];
